const FIXTURE_URL = "../experiments/social-game/fixtures/content.json";
const ASSET_ROOT = "../experiments/social-game/";
const STORAGE_KEY = "seikan-chronicle-demo:v1";
const OWNER_KEY = `${STORAGE_KEY}:owner`;
const MAX_PARTY_SIZE = 4;

const app = document.querySelector("#app");
let content = null;
let store = null;
let storageMode = "persistent";
let storageNotice = "";
let flashMessage = "";
let newThreadDraft = null;
let partyShareMessage = "";
let partyShareError = "";
const consumedPartyQueries = new Set();
let skipLinkBound = false;

const escapeHTML = (value = "") => String(value)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;")
  .replaceAll("'", "&#039;");

const assetURL = (path) => `${ASSET_ROOT}${path}`;
const clone = (value) => JSON.parse(JSON.stringify(value));
const isPlainObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const characterById = (id) => content.characters.find((character) => character.id === id);
const guideById = (id) => content.guides.find((guide) => guide.id === id);
const eventById = (id) => content.events.find((event) => event.id === id);
const formatDate = (value) => String(value).replaceAll("-", ".");
const formatDateTime = (value) => `${String(value).slice(0, 10).replaceAll("-", ".")} ${String(value).slice(11, 16)}`;
const validText = (value, min, max) => typeof value === "string" && value.trim().length >= min && value.trim().length <= max;
const validDate = (value) => typeof value === "string" && !Number.isNaN(Date.parse(value));

function getOwnerId() {
  try {
    const existing = window.localStorage.getItem(OWNER_KEY);
    if (existing && /^traveler-[a-z0-9-]{8,80}$/i.test(existing)) return existing;
    const generated = `traveler-${globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`}`;
    window.localStorage.setItem(OWNER_KEY, generated);
    return generated;
  } catch {
    storageMode = "temporary";
    storageNotice = "保存先を利用できないため、一時利用モードで表示しています。保存成功とは表示しません。";
    return `temporary-${Date.now()}`;
  }
}

function blankStore(owner = getOwnerId()) {
  return { version: 1, ownerId: owner, bookmarks: [], party: [], userThreads: [], userReplies: [], edits: {}, deleted: [], reports: [] };
}

function assertStringArray(value) {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) throw new Error("保存データの配列を確認できません");
}

function assertReply(reply, owner, expectedThreadId = null, allowSeed = false) {
  if (!isPlainObject(reply) || !validText(reply.id, 1, 100) || !validText(reply.author, 1, 24) || !validText(reply.body, 1, 1000) || !validDate(reply.created)) throw new Error("保存された返信を確認できません");
  if (expectedThreadId !== null && reply.threadId !== expectedThreadId) throw new Error("保存された返信の所属を確認できません");
  if (reply.owner !== owner && !(allowSeed && reply.owner === "seed")) throw new Error("保存された返信の所有者を確認できません");
}

function assertThread(thread, owner) {
  if (!isPlainObject(thread) || !validText(thread.id, 1, 100) || !validText(thread.title, 1, 80) || !["質問", "攻略共有", "雑談"].includes(thread.category) || !validText(thread.author, 1, 24) || !validText(thread.body, 1, 1000) || !validDate(thread.created) || thread.owner !== owner || !Array.isArray(thread.replies)) throw new Error("保存されたスレッドを確認できません");
  thread.replies.forEach((reply) => assertReply(reply, owner, thread.id));
}

function validateStoredStore(candidate) {
  if (!isPlainObject(candidate) || candidate.version !== 1 || !/^traveler-[a-z0-9-]{8,80}$/i.test(candidate.ownerId)) throw new Error("保存データの形式が確認できません");
  ["bookmarks", "party", "userThreads", "userReplies", "deleted", "reports"].forEach((key) => { if (!Array.isArray(candidate[key])) throw new Error("保存データの形式が確認できません"); });
  if (!isPlainObject(candidate.edits)) throw new Error("保存データの形式が確認できません");
  assertStringArray(candidate.bookmarks); assertStringArray(candidate.party); assertStringArray(candidate.deleted);
  if (candidate.bookmarks.some((id) => !guideById(id))) throw new Error("保存された記事を確認できません");
  if (candidate.party.some((id) => !characterById(id)) || new Set(candidate.party).size !== candidate.party.length || candidate.party.length > MAX_PARTY_SIZE) throw new Error("保存された編成を確認できません");
  const seedIds = new Set(content.threads.map((thread) => thread.id));
  const ownThreadIds = new Set(); const ownReplyIds = new Set();
  candidate.userThreads.forEach((thread) => { assertThread(thread, candidate.ownerId); if (seedIds.has(thread.id) || ownThreadIds.has(thread.id)) throw new Error("保存されたスレッドIDが重複しています"); ownThreadIds.add(thread.id); thread.replies.forEach((reply) => { if (ownReplyIds.has(reply.id)) throw new Error("保存された返信IDが重複しています"); ownReplyIds.add(reply.id); }); });
  candidate.userReplies.forEach((reply) => { assertReply(reply, candidate.ownerId); if (ownReplyIds.has(reply.id)) throw new Error("保存された返信IDが重複しています"); ownReplyIds.add(reply.id); if (![...seedIds, ...ownThreadIds].includes(reply.threadId)) throw new Error("保存された返信の所属を確認できません"); });
  const ownIds = new Set([...ownThreadIds, ...ownReplyIds]);
  candidate.deleted.forEach((id) => { if (!ownIds.has(id)) throw new Error("削除記録の所有者を確認できません"); });
  Object.entries(candidate.edits).forEach(([id, edit]) => { if (!ownIds.has(id) || !isPlainObject(edit)) throw new Error("編集記録の所有者を確認できません"); if ("title" in edit && !validText(edit.title, 1, 80)) throw new Error("編集されたタイトルを確認できません"); if ("author" in edit && !validText(edit.author, 1, 24)) throw new Error("編集された表示名を確認できません"); if ("body" in edit && !validText(edit.body, 1, 1000)) throw new Error("編集された本文を確認できません"); if (Object.keys(edit).some((key) => !["title", "author", "body"].includes(key))) throw new Error("編集記録の形式が確認できません"); });
  candidate.reports.forEach((report) => { if (!isPlainObject(report) || !validText(report.id, 1, 100) || !["内容が不正確", "困った投稿", "その他"].includes(report.reason) || !validDate(report.created)) throw new Error("通報記録を確認できません"); });
  return candidate;
}

function loadStore() {
  const fresh = blankStore();
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return fresh;
    const parsed = validateStoredStore(JSON.parse(raw));
    return { ...fresh, ...clone(parsed) };
  } catch {
    storageMode = "temporary";
    storageNotice = "保存データを読み込めないため、一時利用モードで表示しています。保存データを初期化すると復旧できます。";
    return fresh;
  }
}

function saveStore() {
  if (storageMode === "temporary") return false;
  try { window.localStorage.setItem(STORAGE_KEY, JSON.stringify(store)); return true; } catch {
    storageMode = "temporary";
    storageNotice = "保存先への書き込みに失敗したため、一時利用モードに切り替えました。保存成功とは表示しません。";
    return false;
  }
}

function commitMutation(mutator) {
  mutator();
  if (storageMode === "temporary") return { persistent: false, temporary: true };
  return saveStore() ? { persistent: true, temporary: false } : { persistent: false, temporary: true };
}

function mutationMessage(result, success, temporary = `${success} このセッション内では反映していますが、再読み込みで消える可能性があります。`) { return result.persistent ? success : temporary; }
function navigateOrRender(hash) { if (window.location.hash === `#${hash}`) render(); else window.location.hash = hash; }

function parseRoute() {
  const raw = window.location.hash.slice(1) || "home";
  const [path, queryString = ""] = raw.split("?");
  return { path, query: new URLSearchParams(queryString) };
}

function navItems() { return [["home", "ホーム"], ["characters", "キャラ図鑑"], ["guides", "攻略記事"], ["community", "掲示板"], ["party", "編成ツール"]]; }

function headerTemplate(route) {
  const active = route.path.startsWith("character/") ? "characters" : route.path.split("/")[0];
  const notice = storageNotice ? `<div class="storage-notice" role="status"><span aria-hidden="true">!</span>${escapeHTML(storageNotice)} <a href="#bookmarks">保存データを確認</a></div>` : "";
  return `<header class="site-header"><div class="header-inner"><a class="brand" href="#home" aria-label="星環クロニクル攻略室 ホーム"><span class="brand-mark" aria-hidden="true">✦</span><span class="brand-copy"><span class="brand-title">星環クロニクル攻略室</span><span class="brand-subtitle">SEIKAN CHRONICLE / FIELD NOTES</span></span></a><nav class="primary-nav" id="primary-nav" aria-label="主要メニュー"><ul>${navItems().map(([path, label]) => `<li><a href="#${path}" ${active === path ? 'aria-current="page"' : ""}>${label}</a></li>`).join("")}</ul></nav><div class="header-tools"><form class="header-search" data-search-form><label for="header-search-input">サイト内検索</label><input id="header-search-input" name="q" type="search" placeholder="キャラ・記事・相談を検索" autocomplete="off" /><button class="icon-button" type="submit" aria-label="検索">⌕</button></form><button class="menu-button" type="button" data-action="toggle-menu" aria-controls="primary-nav" aria-expanded="false" aria-label="メニューを開く">☰</button></div></div>${notice}<div class="status-strip"><div class="header-inner status-inner"><p><span class="gold-text">●</span> 架空ゲームのローカルデモ　/　基準時刻 2026.09.07 21:00 JST</p><p><a class="status-link" href="#bookmarks">保存一覧を見る →</a></p></div></div></header>`;
}

function footerTemplate() { return `<footer class="site-footer"><div class="footer-inner"><div><p class="footer-brand">星環クロニクル攻略室</p><p>架空ゲームの学習用デモ。実在のゲーム・運営とは関係ありません。</p></div><div class="footer-links"><a href="#bookmarks?panel=rules">利用ルール</a><a href="#bookmarks?panel=privacy">プライバシー</a><a href="#bookmarks?panel=sources">素材出典</a></div></div></footer>`; }
function breadcrumbs(items) { return `<nav aria-label="パンくず"><ol class="breadcrumb-list">${items.map((item, index) => `<li>${index < items.length - 1 && item.href ? `<a href="${item.href}">${escapeHTML(item.label)}</a>` : escapeHTML(item.label)}</li>`).join("")}</ol></nav>`; }
function feedbackBanner() { if (!flashMessage) return ""; const message = escapeHTML(flashMessage); flashMessage = ""; return `<div class="feedback-banner" role="status">${message}</div>`; }
function characterCard(character, extraClass = "") { return `<a class="character-card ${extraClass}" href="#character/${character.id}"><img src="${assetURL(character.image)}" alt="${escapeHTML(character.name)}のキャラクターアイコン" loading="lazy" /><span class="character-info"><span class="character-name">${escapeHTML(character.name)}</span><span class="character-meta">${escapeHTML(character.element)} / ${escapeHTML(character.role)} / ${escapeHTML(character.rarity)}</span><span class="character-rating">★ ${escapeHTML(character.rating.toFixed(1))}</span></span></a>`; }
function partyCandidateCard(character) { const selected = store.party.includes(character.id); const disabled = !selected && store.party.length >= MAX_PARTY_SIZE; return `<article class="character-card party-candidate ${selected ? "is-selected" : ""}"><a href="#character/${character.id}"><img src="${assetURL(character.image)}" alt="${escapeHTML(character.name)}のキャラクターアイコン" loading="lazy" /><span class="character-info"><span class="character-name">${escapeHTML(character.name)}</span><span class="character-meta">${escapeHTML(character.element)} / ${escapeHTML(character.role)}</span></span></a><button class="subtle-button party-add-button" type="button" data-action="${selected ? "remove-party" : "add-party"}" data-character-id="${character.id}" ${disabled ? "disabled" : ""}>${selected ? "編成から外す" : disabled ? "満員" : "編成に追加"}</button></article>`; }
function guideListItem(guide) { const bookmarked = store.bookmarks.includes(guide.id); return `<article class="guide-block"><div class="guide-block-meta"><span class="tag">${escapeHTML(guide.category)}</span><time datetime="${guide.updated}">${escapeHTML(formatDate(guide.updated))}</time></div><a class="guide-block-link" href="#guide/${guide.id}"><span class="guide-title">${escapeHTML(guide.title)}</span><span class="guide-summary">${escapeHTML(guide.summary)}</span></a><div class="guide-block-footer"><span>${guide.sections.length}章　/　関連キャラ ${guide.characters.length}体</span><span class="bookmark-state">${bookmarked ? "保存中" : "未保存"}</span></div></article>`; }
function threadRow(thread) { return `<a class="thread-row" href="#thread/${thread.id}"><span><span class="thread-title">${escapeHTML(thread.title)}</span><span class="thread-sub"><span class="tag">${escapeHTML(thread.category)}</span>${escapeHTML(thread.author)}　${escapeHTML(formatDateTime(thread.created))}</span></span><span class="thread-count">返信 ${thread.replies?.length ?? 0}</span></a>`; }

function homeView() {
  const event = eventById("e01"); const threads = allThreads().sort((a, b) => String(b.created).localeCompare(String(a.created))).slice(0, 3);
  return `${feedbackBanner()}<div class="page-heading home-heading"><div><p class="eyebrow">FIELD NOTES / 2026.09.07</p><h1>今日の攻略ルート</h1><p class="lede">イベント、手持ちキャラ、攻略の疑問へ。次の一手をすぐ見つける攻略室です。</p></div><div class="heading-aside"><strong>03</strong>開催中のイベント</div></div><nav class="entry-strip" aria-label="最初に見る入口"><a href="#guide/g01"><span class="entry-number">01</span><span><strong>初心者ガイド</strong><small>最初の3日を読む</small></span><span aria-hidden="true">→</span></a><a href="#characters"><span class="entry-number">02</span><span><strong>キャラ図鑑</strong><small>手持ちの役割を確認</small></span><span aria-hidden="true">→</span></a><a href="#community"><span class="entry-number">03</span><span><strong>掲示板</strong><small>みんなの相談を見る</small></span><span aria-hidden="true">→</span></a></nav><div class="home-grid"><div class="stack"><section class="paper-panel event-feature" aria-labelledby="event-heading"><div class="event-image"><img src="${assetURL(event.image)}" alt="${escapeHTML(event.title)}のイベントイメージ" /></div><div class="event-copy"><div class="panel-kicker"><p>EVENT / PICK UP</p><span class="status-pill">${escapeHTML(event.status)}</span></div><h2 id="event-heading">${escapeHTML(event.title)}</h2><p>${escapeHTML(event.description)}</p><div class="event-meta"><span>${escapeHTML(formatDate(event.start))} — ${escapeHTML(formatDate(event.end))}</span><span>報酬 ${escapeHTML(event.rewards[0])}</span></div><div class="action-row"><a class="button-link" href="#event/${event.id}">イベント詳細を見る <span aria-hidden="true">→</span></a><a class="subtle-button" href="#events">イベント一覧</a><a class="subtle-button" href="#guide/${event.guide}">攻略記事</a></div></div></section><section class="section-block" aria-labelledby="guides-heading"><div class="section-head"><h2 id="guides-heading">攻略の入口</h2><a href="#guides">8記事を見る →</a></div><div class="guide-list guide-list--home">${content.guides.slice(0, 4).map(guideListItem).join("")}</div></section><section class="section-block" aria-labelledby="roster-heading"><div class="section-head"><h2 id="roster-heading">まず見る4人</h2><a href="#characters">図鑑をひらく →</a></div><div class="character-preview-grid">${content.characters.slice(0, 4).map((character) => characterCard(character)).join("")}</div></section></div><aside class="stack"><section class="paper-panel panel-pad" aria-labelledby="start-heading"><div class="panel-kicker"><p>START HERE</p><span class="tag tag--gold">3分で確認</span></div><h2 id="start-heading">迷ったらこの順番</h2><p class="update-note">新しく始めた旅人向けに、読む場所を3つに絞りました。</p><ul class="quick-list"><li><a href="#guide/g01"><span><strong>01</strong>　最初の3日</span></a></li><li><a href="#characters"><span><strong>02</strong>　手持ちを確認</span></a></li><li><a href="#party"><span><strong>03</strong>　4枠を組む</span></a></li></ul></section><section class="paper-panel panel-pad" aria-labelledby="community-heading"><div class="section-head"><h2 id="community-heading">最近の相談</h2><a href="#community">掲示板へ →</a></div><div class="community-preview">${threads.map(threadRow).join("")}</div></section><section class="paper-panel panel-pad"><p class="eyebrow">更新情報</p><p class="update-note"><strong>2026.09.07</strong><br />星環祭の報酬交換ガイドを追加しました。</p><a class="action-link" href="#bookmarks">保存した記事を確認 →</a></section></aside></div>`;
}

function directoryView() { return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "キャラ図鑑" }])}<div class="page-heading"><div><p class="eyebrow">CHARACTER ARCHIVE / 12 RECORDS</p><h1>キャラ図鑑</h1><p class="lede">属性、役割、レア度から、いまの編成に必要な一人を探します。</p></div><div class="heading-aside"><strong id="character-count">12</strong>件の記録</div></div><section class="directory-toolbar" aria-label="キャラの絞り込み"><div class="field"><label for="character-query">名前・能力で検索</label><input id="character-query" type="search" placeholder="例：アカリ" data-character-filter="query" /></div><div class="field"><label for="element-filter">属性</label><select id="element-filter" data-character-filter="element"><option value="">すべて</option><option>火</option><option>水</option><option>風</option><option>光</option></select></div><div class="field"><label for="role-filter">役割</label><select id="role-filter" data-character-filter="role"><option value="">すべて</option><option>攻撃</option><option>支援</option><option>防御</option></select></div><div class="field"><label for="rarity-filter">レア度</label><select id="rarity-filter" data-character-filter="rarity"><option value="">すべて</option><option>SSR</option><option>SR</option></select></div><div class="field"><label for="sort-filter">並べ替え</label><select id="sort-filter" data-character-filter="sort"><option value="name">名前順</option><option value="rating">評価順</option></select></div><button class="subtle-button" type="button" data-action="reset-character-filter">条件をリセット</button></section><p class="result-line" id="character-result-line" aria-live="polite"><strong>12件</strong>を表示中</p><div class="character-grid" id="character-grid"></div>`; }

function detailView(character) { const partners = character.partners.map(characterById).filter(Boolean); const relatedGuides = content.guides.filter((guide) => guide.characters.includes(character.id)).slice(0, 2); return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "キャラ図鑑", href: "#characters" }, { label: character.name }])}<section class="paper-panel detail-hero" aria-labelledby="detail-title"><div class="detail-portrait"><img src="${assetURL(character.image)}" alt="${escapeHTML(character.name)}のキャラクターアイコン" /></div><div class="detail-summary"><p class="eyebrow">CHARACTER RECORD / ${escapeHTML(character.id.toUpperCase())}</p><h1 id="detail-title">${escapeHTML(character.name)}</h1><p class="detail-subtitle">${escapeHTML(character.element)}属性・${escapeHTML(character.role)}　/　${escapeHTML(character.rarity)}</p><div class="detail-tags"><span class="tag">${escapeHTML(character.element)}</span><span class="tag">${escapeHTML(character.role)}</span><span class="tag tag--gold">${escapeHTML(character.rarity)}</span></div><div class="rating-block"><span class="rating-number">${escapeHTML(character.rating.toFixed(1))}</span><span class="rating-label">総合評価</span></div><p class="detail-subtitle">役割の異なる仲間と組ませると、持ち味を発揮します。</p><div class="action-row"><a class="button-link" href="#party?add=${character.id}">編成に追加する <span aria-hidden="true">→</span></a><a class="subtle-button" href="#characters">図鑑へ戻る</a></div></div></section><div class="detail-grid"><section class="paper-panel panel-pad" aria-labelledby="ability-heading"><div class="panel-kicker"><p>ABILITY PROFILE</p><span class="tag">${escapeHTML(character.id)}</span></div><h2 id="ability-heading">能力の見取り図</h2><div class="stat-grid"><div class="stat"><span class="stat-label">攻撃</span><strong class="stat-value">${escapeHTML(character.attack.toLocaleString("ja-JP"))}</strong></div><div class="stat"><span class="stat-label">HP</span><strong class="stat-value">${escapeHTML(character.hp.toLocaleString("ja-JP"))}</strong></div></div><div class="rule"></div><div class="skill-callout"><strong>固有スキル</strong><p>${escapeHTML(character.skill)}</p></div></section><section class="paper-panel panel-pad" aria-labelledby="materials-heading"><div class="panel-kicker"><p>GROWTH NOTES</p><span class="tag tag--gold">育成</span></div><h2 id="materials-heading">必要素材</h2><ul class="materials">${character.materials.map((material) => { const [name, amount] = material.split("×"); return `<li><span>${escapeHTML(name)}</span><strong>×${escapeHTML(amount)}</strong></li>`; }).join("")}</ul><p class="muted" style="font-size: 13px;">育成素材の入手先は攻略記事で確認できます。</p></section></div><section class="paper-panel panel-pad section-block" aria-labelledby="partners-heading"><div class="panel-kicker"><p>PARTY SYNERGY</p><span class="tag">関連キャラ</span></div><h2 id="partners-heading">相性のよい記録</h2><p class="muted">このキャラと組みやすいパートナー候補です。</p><div class="partners">${partners.map((partner) => `<a class="partner" href="#character/${partner.id}"><img src="${assetURL(partner.image)}" alt="" loading="lazy" /><span>${escapeHTML(partner.name)}　${escapeHTML(partner.role)}</span></a>`).join("")}</div></section><section class="section-block" aria-labelledby="related-guides-heading"><div class="section-head"><h2 id="related-guides-heading">関連する攻略</h2><a href="#guides">記事一覧へ →</a></div><div class="guide-grid guide-grid--compact">${relatedGuides.map(guideListItem).join("")}</div></section>`; }

function guidesView() { return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "攻略記事" }])}<div class="page-heading"><div><p class="eyebrow">GUIDE INDEX / 8 ARTICLES</p><h1>攻略記事</h1><p class="lede">初心者の進め方から育成、ボス、編成まで、目的から記事を選べます。</p></div><div class="heading-aside"><strong>08</strong>記事</div></div><section class="list-toolbar" aria-label="攻略記事の絞り込み"><div class="field"><label for="guide-query">記事を検索</label><input id="guide-query" type="search" placeholder="タイトル・概要を検索" data-guide-filter="query" /></div><div class="field"><label for="guide-category">カテゴリ</label><select id="guide-category" data-guide-filter="category"><option value="">すべて</option><option>初心者</option><option>育成</option><option>ボス</option><option>編成</option></select></div><button class="subtle-button" type="button" data-action="reset-guide-filter">条件をリセット</button></section><p class="result-line" id="guide-result-line" aria-live="polite"><strong>8記事</strong>を表示中</p><div class="guide-grid" id="guide-grid">${content.guides.map(guideListItem).join("")}</div>`; }

function guideDetailView(guide, route) { const bookmarked = store.bookmarks.includes(guide.id); const related = guide.characters.map(characterById).filter(Boolean); return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "攻略記事", href: "#guides" }, { label: guide.title }])}<div class="article-layout"><article class="article-main paper-panel panel-pad"><div class="article-header"><div class="article-meta"><span class="tag">${escapeHTML(guide.category)}</span><time datetime="${guide.updated}">${escapeHTML(formatDate(guide.updated))} 更新</time></div><h1>${escapeHTML(guide.title)}</h1><p class="article-summary">${escapeHTML(guide.summary)}</p><button class="bookmark-button ${bookmarked ? "is-bookmarked" : ""}" type="button" data-action="toggle-bookmark" data-guide-id="${guide.id}" aria-pressed="${bookmarked}">${bookmarked ? "★ 保存中" : "☆ 記事を保存"}</button></div><div class="article-body">${guide.sections.map((section, index) => `<section id="guide-${guide.id}-section-${index}" class="article-section"><h2>${escapeHTML(section.heading)}</h2><p>${escapeHTML(section.body)}</p></section>`).join("")}<section class="article-related"><h2>関連キャラ</h2><div class="partners">${related.map((character) => `<a class="partner" href="#character/${character.id}"><img src="${assetURL(character.image)}" alt="" loading="lazy" /><span>${escapeHTML(character.name)}　${escapeHTML(character.role)}</span></a>`).join("")}</div></section></div></article><aside class="article-aside"><section class="paper-panel panel-pad toc-panel"><p class="eyebrow">CONTENTS</p><h2>目次</h2><ol>${guide.sections.map((section, index) => `<li><a href="#guide/${guide.id}?section=${index}">${escapeHTML(section.heading)}</a></li>`).join("")}</ol></section><section class="paper-panel panel-pad"><p class="eyebrow">NEXT STEP</p><h3>キャラの使い方を見る</h3><p class="muted">関連キャラの能力と編成相性を確認できます。</p><a class="action-link" href="#characters">図鑑へ →</a></section></aside></div>`; }

function eventsView() { return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "イベント" }])}<div class="page-heading"><div><p class="eyebrow">EVENT CALENDAR / 03 RECORDS</p><h1>開催イベント</h1><p class="lede">ゲーム内の基準日程に沿った、開催中イベントの一覧です。</p></div><div class="heading-aside"><strong>03</strong>開催中</div></div><div class="event-list">${content.events.map((event) => `<article class="paper-panel event-list-item"><a class="event-list-image" href="#event/${event.id}"><img src="${assetURL(event.image)}" alt="${escapeHTML(event.title)}のイベントイメージ" loading="lazy" /></a><div class="event-list-copy"><div class="panel-kicker"><span class="status-pill">${escapeHTML(event.status)}</span><span class="tag">${escapeHTML(formatDate(event.start))} — ${escapeHTML(formatDate(event.end))}</span></div><h2><a href="#event/${event.id}">${escapeHTML(event.title)}</a></h2><p>${escapeHTML(event.description)}</p><div class="event-rewards"><strong>主な報酬</strong><span>${event.rewards.map(escapeHTML).join("　/　")}</span></div><a class="action-link" href="#event/${event.id}">詳細を見る →</a></div></article>`).join("")}</div>`; }
function eventDetailView(event) { const guide = guideById(event.guide); return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "イベント", href: "#events" }, { label: event.title }])}<article class="event-detail"><section class="paper-panel event-detail-head"><div class="event-detail-image"><img src="${assetURL(event.image)}" alt="${escapeHTML(event.title)}のイベントイメージ" /></div><div class="event-detail-copy"><p class="eyebrow">EVENT RECORD / ${escapeHTML(event.id.toUpperCase())}</p><div class="detail-tags"><span class="status-pill">${escapeHTML(event.status)}</span><span class="tag">${escapeHTML(formatDate(event.start))} — ${escapeHTML(formatDate(event.end))}</span></div><h1>${escapeHTML(event.title)}</h1><p>${escapeHTML(event.description)}</p></div></section><div class="event-detail-grid"><section class="paper-panel panel-pad"><p class="eyebrow">REWARDS</p><h2>報酬</h2><ul class="reward-list">${event.rewards.map((reward) => `<li><span aria-hidden="true">✦</span>${escapeHTML(reward)}</li>`).join("")}</ul><div class="rule"></div><p class="muted">期間は固定日程の日付で表示しています。実時間による終了判定は行いません。</p></section><section class="paper-panel panel-pad"><p class="eyebrow">RELATED GUIDE</p><h2>攻略の入口</h2><p class="muted">イベントの進め方を記事で確認できます。</p>${guide ? `<a class="related-guide" href="#guide/${guide.id}"><strong>${escapeHTML(guide.title)}</strong><span>${escapeHTML(guide.summary)}</span><span class="action-link">記事を読む →</span></a>` : ""}</section></div></article>`; }

function searchView(term) { const normalized = term.trim().toLocaleLowerCase("ja"); const results = []; if (normalized) { content.characters.forEach((item) => { const text = [item.name, item.element, item.role, item.rarity, item.skill, ...item.materials].join(" "); if (text.toLocaleLowerCase("ja").includes(normalized)) results.push({ type: "キャラ", title: item.name, copy: `${item.element}・${item.role} / ${item.skill}`, href: `#character/${item.id}` }); }); content.guides.forEach((item) => { const text = [item.title, item.summary, item.category, ...item.sections.flatMap((section) => [section.heading, section.body])].join(" "); if (text.toLocaleLowerCase("ja").includes(normalized)) results.push({ type: "攻略記事", title: item.title, copy: item.summary, href: `#guide/${item.id}` }); }); allThreads().forEach((item) => { const text = [item.title, item.body, item.category, item.author, ...item.replies.flatMap((reply) => [reply.author, reply.body])].join(" "); if (text.toLocaleLowerCase("ja").includes(normalized)) results.push({ type: "掲示板", title: item.title, copy: item.body, href: `#thread/${item.id}` }); }); } return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "検索結果" }])}<div class="page-heading"><div><p class="eyebrow">SITE SEARCH / ${normalized ? "RESULT" : "READY"}</p><h1>${normalized ? `「${escapeHTML(term)}」の検索結果` : "サイト内検索"}</h1><p class="lede">キャラの能力・育成素材、攻略記事の各章、掲示板の返信まで検索します。</p></div><div class="heading-aside"><strong>${normalized ? results.length : 0}</strong>${normalized ? "件" : "検索語を入力"}</div></div>${normalized ? (results.length ? `<div class="search-results">${results.map((result) => `<a class="search-result" href="${result.href}"><span class="search-result-type">${escapeHTML(result.type)}</span><div class="search-result-title">${escapeHTML(result.title)}</div><div class="search-result-copy">${escapeHTML(result.copy)}</div></a>`).join("")}</div>` : `<div class="empty-state"><strong>該当する記録はありません。</strong><p>検索語を変えて、もう一度お試しください。</p><a class="subtle-button" href="#home">ホームへ戻る</a></div>`) : `<div class="paper-panel panel-pad"><p class="muted">ヘッダーの検索欄から、たとえば「結晶」や「アカリ」を検索できます。</p></div>`}`; }

function partyView() { const members = store.party.map(characterById).filter(Boolean); const shareURL = `${window.location.origin}${window.location.pathname}#party?share=${store.party.join(",")}`; const message = partyShareError ? `<div class="inline-warning" role="alert">${escapeHTML(partyShareError)}</div>` : partyShareMessage ? `<div class="feedback-banner" role="status">${escapeHTML(partyShareMessage)}</div>` : ""; return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "編成ツール" }])}<div class="page-heading"><div><p class="eyebrow">PARTY BUILDER / 4 SLOTS</p><h1>編成ツール</h1><p class="lede">4枠にキャラを追加して、役割のバランスを確認します。同じキャラは一度だけ選べます。</p></div><div class="heading-aside"><strong>${members.length} / 4</strong>編成中</div></div>${message}<section class="party-board paper-panel panel-pad"><div class="section-head"><h2>現在の編成</h2><span class="tag">${members.length === 4 ? "満員" : `${4 - members.length}枠空き`}</span></div><div class="party-slots">${Array.from({ length: MAX_PARTY_SIZE }, (_, index) => { const member = members[index]; return member ? `<article class="party-slot is-filled"><img src="${assetURL(member.image)}" alt="${escapeHTML(member.name)}のキャラクターアイコン" /><div><strong>${escapeHTML(member.name)}</strong><span>${escapeHTML(member.element)} / ${escapeHTML(member.role)}</span></div><button class="icon-button light-icon" type="button" data-action="remove-party" data-character-id="${member.id}" aria-label="${escapeHTML(member.name)}を編成から外す">×</button></article>` : `<div class="party-slot is-empty"><span class="slot-number">0${index + 1}</span><span>キャラを選択</span></div>`; }).join("")}</div><div class="party-explanation"><strong>編成のルール</strong><p>同じキャラの重複追加はできません。4枠が埋まると、候補の追加ボタンは「満員」になります。1枠外すと、別のキャラを追加できます。</p></div><div class="action-row"><button class="primary-button" type="button" data-action="copy-party-url" ${members.length !== 4 ? "disabled" : ""}>編成URLをコピー</button><label class="share-fallback"><span>共有URL（コピーできない場合は選択）</span><input id="party-share-url" type="text" value="${escapeHTML(shareURL)}" readonly /></label></div></section><section class="section-block" aria-labelledby="candidate-heading"><div class="section-head"><h2 id="candidate-heading">キャラを追加</h2><span class="muted">${content.characters.length}体</span></div><div class="character-grid party-candidate-grid">${content.characters.map(partyCandidateCard).join("")}</div></section>`; }

function communityView() { const threads = allThreads().sort((a, b) => String(b.created).localeCompare(String(a.created))); return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "掲示板" }])}<div class="page-heading"><div><p class="eyebrow">COMMUNITY BOARD / 06 THREADS</p><h1>掲示板</h1><p class="lede">攻略の相談、周回の共有、今日の冒険。返信数と新着順から読みたい話題を選べます。</p></div><div class="heading-aside"><strong id="thread-count">${threads.length}</strong>スレッド</div></div><div class="board-actions"><a class="button-link" href="#new-thread">新しく相談する <span aria-hidden="true">→</span></a><a class="subtle-button" href="#bookmarks?panel=rules">利用ルール</a></div><section class="list-toolbar board-toolbar" aria-label="掲示板の絞り込み"><div class="field"><label for="thread-query">スレッドを検索</label><input id="thread-query" type="search" placeholder="タイトル・本文・返信を検索" data-thread-filter="query" /></div><div class="field"><label for="thread-category">カテゴリ</label><select id="thread-category" data-thread-filter="category"><option value="">すべて</option><option>質問</option><option>攻略共有</option><option>雑談</option></select></div><div class="field"><label for="thread-sort">並べ替え</label><select id="thread-sort" data-thread-filter="sort"><option value="new">新着順</option><option value="replies">返信数順</option></select></div><button class="subtle-button" type="button" data-action="reset-thread-filter">条件をリセット</button></section><p class="result-line" id="thread-result-line" aria-live="polite"><strong>${threads.length}件</strong>を表示中</p><div class="thread-list-panel paper-panel" id="thread-list">${threads.map(threadRow).join("")}</div>`; }

function postActions(post, threadId, kind) { if (post.owner === store.ownerId) return `<div class="post-actions"><a class="subtle-button" href="#thread/${threadId}?edit=${kind}&post=${encodeURIComponent(post.id)}">編集</a><button class="subtle-button" type="button" data-action="delete-open" data-delete-kind="${kind}" data-delete-id="${escapeHTML(post.id)}" data-thread-id="${threadId}">削除</button></div>`; if (post.owner !== "seed") return ""; return `<div class="post-actions"><button class="subtle-button" type="button" data-action="report-open" data-report-id="${escapeHTML(post.id)}">通報デモ</button></div>`; }
function editForm(post, threadId, kind) { const isThread = kind === "thread"; return `<form class="post-edit-form" data-edit-form data-edit-kind="${kind}" data-edit-id="${escapeHTML(post.id)}" data-thread-id="${threadId}"><p class="eyebrow">EDIT / YOUR POST</p>${isThread ? `<div class="field"><label for="edit-title">タイトル <span>1〜80文字</span></label><input id="edit-title" name="title" value="${escapeHTML(post.title)}" maxlength="80" required /></div>` : ""}<div class="field"><label for="edit-author">表示名 <span>${isThread ? "1〜24文字" : "空欄は名無しの旅人"}</span></label><input id="edit-author" name="author" value="${escapeHTML(post.author)}" maxlength="24" ${isThread ? "required" : ""} /></div><div class="field"><label for="edit-body">本文 <span>1〜1000文字</span></label><textarea id="edit-body" name="body" rows="6" maxlength="1000" required>${escapeHTML(post.body)}</textarea></div><p class="form-error" data-form-error></p><div class="action-row"><button class="primary-button" type="submit">変更を保存</button><a class="subtle-button" href="#thread/${threadId}">キャンセル</a></div></form>`; }
function threadDetailView(thread, route) { const editing = route.query.get("edit"); const editingId = route.query.get("post"); const threadBody = editing === "thread" && editingId === thread.id ? editForm(thread, thread.id, "thread") : `<div class="post-body">${escapeHTML(thread.body)}</div>`; return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "掲示板", href: "#community" }, { label: thread.title }])}<article class="thread-detail"><section class="paper-panel thread-parent"><div class="post-meta"><span class="tag">${escapeHTML(thread.category)}</span><span>${escapeHTML(thread.author)}</span><time datetime="${thread.created}">${escapeHTML(formatDateTime(thread.created))}</time></div><h1>${escapeHTML(thread.title)}</h1>${threadBody}${editing !== "thread" ? postActions(thread, thread.id, "thread") : ""}</section><section class="thread-replies" aria-labelledby="reply-heading"><div class="section-head"><h2 id="reply-heading">返信</h2><span class="tag">${thread.replies.length}件</span></div>${thread.replies.length ? thread.replies.map((reply) => { const replyEditing = editing === "reply" && editingId === reply.id; return `<article class="paper-panel reply-post"><div class="post-meta"><span>${escapeHTML(reply.author)}</span><time datetime="${reply.created}">${escapeHTML(formatDateTime(reply.created))}</time></div>${replyEditing ? editForm(reply, thread.id, "reply") : `<div class="post-body">${escapeHTML(reply.body)}</div>${postActions(reply, thread.id, "reply")}`}</article>`; }).join("") : `<div class="empty-state">まだ返信はありません。最初の一言を投稿できます。</div>`}</section><section class="paper-panel panel-pad reply-composer"><p class="eyebrow">JOIN THE CONVERSATION</p><h2>返信する</h2><form data-reply-form data-thread-id="${thread.id}"><div class="form-grid"><div class="field"><label for="reply-author">表示名 <span>空欄は名無しの旅人</span></label><input id="reply-author" name="author" maxlength="24" /></div><div class="field field-wide"><label for="reply-body">本文 <span>1〜1000文字</span></label><textarea id="reply-body" name="body" rows="5" maxlength="1000" required></textarea></div></div><p class="form-error" data-form-error></p><div class="action-row"><button class="primary-button" type="submit">返信を投稿</button><a class="subtle-button" href="#community">掲示板へ戻る</a></div></form></section></article>${modalTemplate()}`; }
function newThreadView(confirm = false) { const draft = newThreadDraft ?? { category: "質問", title: "", author: "", body: "" }; if (confirm) return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "掲示板", href: "#community" }, { label: "内容の確認" }])}<section class="paper-panel confirm-panel"><p class="eyebrow">NEW THREAD / CONFIRM</p><h1>投稿内容を確認</h1><p class="muted">この内容で投稿します。修正する場合は戻るを選んでください。</p><dl class="confirm-list"><div><dt>カテゴリ</dt><dd>${escapeHTML(draft.category)}</dd></div><div><dt>タイトル</dt><dd>${escapeHTML(draft.title)}</dd></div><div><dt>表示名</dt><dd>${escapeHTML(draft.author)}</dd></div><div><dt>本文</dt><dd>${escapeHTML(draft.body)}</dd></div></dl><div class="action-row"><button class="primary-button" type="button" data-action="new-thread-post">この内容で投稿</button><a class="subtle-button" href="#new-thread">修正する</a><a class="subtle-button" href="#community">キャンセル</a></div></section>`; return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "掲示板", href: "#community" }, { label: "新規投稿" }])}<section class="paper-panel form-panel"><p class="eyebrow">NEW THREAD / WRITE</p><h1>新しく相談する</h1><p class="lede">タイトル・表示名・本文を入力してから、確認画面へ進みます。</p><form data-new-thread-form><div class="field"><label for="new-category">カテゴリ</label><select id="new-category" name="category"><option>質問</option><option>攻略共有</option><option>雑談</option></select></div><div class="field"><label for="new-title">タイトル <span>1〜80文字</span></label><input id="new-title" name="title" maxlength="80" value="${escapeHTML(draft.title)}" required /></div><div class="field"><label for="new-author">表示名 <span>1〜24文字</span></label><input id="new-author" name="author" maxlength="24" value="${escapeHTML(draft.author)}" required /></div><div class="field"><label for="new-body">本文 <span>1〜1000文字</span></label><textarea id="new-body" name="body" rows="9" maxlength="1000" required>${escapeHTML(draft.body)}</textarea></div><p class="form-error" data-form-error></p><div class="action-row"><button class="primary-button" type="submit">確認画面へ</button><a class="subtle-button" href="#community">掲示板へ戻る</a></div></form></section>`; }
function bookmarksView(route) { const saved = store.bookmarks.map(guideById).filter(Boolean); return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "保存一覧" }])}<div class="page-heading"><div><p class="eyebrow">SAVED NOTES / LOCAL ARCHIVE</p><h1>保存一覧と案内</h1><p class="lede">保存した攻略記事と、このデモの利用ルールを確認できます。</p></div><div class="heading-aside"><strong>${saved.length}</strong>保存記事</div></div><div class="saved-layout"><div><section class="section-head"><h2>保存した記事</h2><span class="muted">${saved.length}件</span></section>${saved.length ? `<div class="guide-grid">${saved.map(guideListItem).join("")}</div>` : `<div class="empty-state">保存した記事はありません。記事詳細の「記事を保存」から追加できます。</div>`}</div><aside class="saved-aside"><section class="paper-panel panel-pad storage-panel"><p class="eyebrow">STORAGE</p><h2>このデモの保存先</h2><p class="muted">${storageMode === "persistent" ? "保存はこのサイト専用の領域に行われ、再読み込み後も維持されます。" : "保存先を利用できないため、一時利用中です。保存操作は成功扱いにしません。"}</p><button class="subtle-button" type="button" data-action="reset-open">保存データを初期化</button></section><section class="paper-panel panel-pad info-panel" id="rules"><p class="eyebrow">RULES</p><h2>利用ルール</h2><p>ここは架空ゲームの相談デモです。投稿内容は実際のサービスへ送信されません。自分の投稿だけ編集・削除できます。他人の投稿は通報デモで理由を選べます。</p></section><section class="paper-panel panel-pad info-panel" id="privacy"><p class="eyebrow">PRIVACY</p><h2>プライバシー</h2><p>ログインや外部送信はありません。投稿・保存・編成はこのデモ専用の保存領域に記録されます。初期化ではこのデモの保存キーだけを削除します。</p></section><section class="paper-panel panel-pad info-panel" id="sources"><p class="eyebrow">SOURCE CREDIT</p><h2>素材出典</h2><p>画面内のキャラクターとイベント画像は、実験用に用意されたオリジナルSVG素材です。ゲーム、人物、運営、課金サービスとは関係ありません。</p></section></aside></div>${modalTemplate("reset")}`; }
function modalTemplate(kind = "report") { if (kind === "reset") return `<div class="modal-backdrop" id="reset-modal" hidden><section class="modal" role="dialog" aria-modal="true" aria-labelledby="reset-title"><button class="modal-close" type="button" data-action="reset-cancel" aria-label="閉じる">×</button><p class="eyebrow">RESET / THIS DEMO ONLY</p><h2 id="reset-title">保存データを初期化しますか？</h2><p>保存記事・編成・自分の投稿を初期状態に戻します。他サイトのデータには触れません。</p><div class="action-row"><button class="subtle-button" type="button" data-action="reset-cancel">取消</button><button class="primary-button" type="button" data-action="reset-confirm">初期化する</button></div></section></div>`; return `<div class="modal-backdrop" id="action-modal" hidden><section class="modal" role="dialog" aria-modal="true" aria-labelledby="report-title"><button class="modal-close" type="button" data-action="modal-close" aria-label="閉じる">×</button><p class="eyebrow">REPORT DEMO / NO SEND</p><h2 id="report-title">通報理由を選択</h2><p>実際の送信は行いません。理由を選び、デモ完了を確認します。元の投稿は削除されません。</p><form data-report-form><input type="hidden" name="postId" /><div class="field"><label for="report-reason">理由</label><select id="report-reason" name="reason" required><option value="">選択してください</option><option>内容が不正確</option><option>困った投稿</option><option>その他</option></select></div><div class="action-row"><button class="subtle-button" type="button" data-action="modal-close">取消</button><button class="primary-button" type="submit">デモを完了</button></div></form></section></div>`; }
function notFoundView(label = "お探しの記録") { return `${feedbackBanner()}${breadcrumbs([{ label: "ホーム", href: "#home" }, { label: "見つかりません" }])}<section class="empty-state"><h1>${escapeHTML(label)}が見つかりません</h1><p>URLを確認するか、一覧から記録を選んでください。</p><a class="subtle-button" href="#home">ホームへ戻る</a></section>`; }

function allThreads() {
  const deleted = new Set(store.deleted); const edits = store.edits ?? {}; const threads = content.threads.map(clone).filter((thread) => !deleted.has(thread.id)); threads.push(...store.userThreads.map(clone).filter((thread) => !deleted.has(thread.id))); const byId = new Map(threads.map((thread) => [thread.id, thread]));
  byId.forEach((thread) => { if (edits[thread.id]) Object.assign(thread, edits[thread.id]); thread.replies = (thread.replies ?? []).filter((reply) => !deleted.has(reply.id)).map((reply) => edits[reply.id] ? { ...reply, ...edits[reply.id] } : reply); });
  store.userReplies.forEach((reply) => { if (deleted.has(reply.id)) return; const thread = byId.get(reply.threadId); if (thread) thread.replies.push(edits[reply.id] ? { ...reply, ...edits[reply.id] } : clone(reply)); });
  return [...byId.values()];
}

function renderCharacters() { const grid = document.querySelector("#character-grid"); if (!grid) return; const query = document.querySelector("[data-character-filter='query']")?.value.trim().toLocaleLowerCase("ja") ?? ""; const element = document.querySelector("[data-character-filter='element']")?.value ?? ""; const role = document.querySelector("[data-character-filter='role']")?.value ?? ""; const rarity = document.querySelector("[data-character-filter='rarity']")?.value ?? ""; const sort = document.querySelector("[data-character-filter='sort']")?.value ?? "name"; const filtered = content.characters.filter((character) => { const text = [character.name, character.skill, ...character.materials].join(" ").toLocaleLowerCase("ja"); return (!query || text.includes(query)) && (!element || character.element === element) && (!role || character.role === role) && (!rarity || character.rarity === rarity); }).sort((a, b) => sort === "rating" ? b.rating - a.rating : a.name.localeCompare(b.name, "ja")); grid.innerHTML = filtered.length ? filtered.map((character) => characterCard(character, "directory-card")).join("") : `<div class="empty-state" style="grid-column:1/-1"><strong>条件に一致するキャラはいません。</strong><p>条件を変えるか、リセットして12件に戻してください。</p></div>`; const line = document.querySelector("#character-result-line"); if (line) line.innerHTML = `<strong>${filtered.length}件</strong>を表示中`; const count = document.querySelector("#character-count"); if (count) count.textContent = filtered.length; }
function renderGuides() { const grid = document.querySelector("#guide-grid"); if (!grid) return; const query = document.querySelector("[data-guide-filter='query']")?.value.trim().toLocaleLowerCase("ja") ?? ""; const category = document.querySelector("[data-guide-filter='category']")?.value ?? ""; const filtered = content.guides.filter((guide) => (!category || guide.category === category) && (!query || [guide.title, guide.summary, ...guide.sections.flatMap((section) => [section.heading, section.body])].join(" ").toLocaleLowerCase("ja").includes(query))); grid.innerHTML = filtered.length ? filtered.map(guideListItem).join("") : `<div class="empty-state" style="grid-column:1/-1"><strong>該当する記事はありません。</strong></div>`; const line = document.querySelector("#guide-result-line"); if (line) line.innerHTML = `<strong>${filtered.length}記事</strong>を表示中`; }
function renderThreads() { const list = document.querySelector("#thread-list"); if (!list) return; const query = document.querySelector("[data-thread-filter='query']")?.value.trim().toLocaleLowerCase("ja") ?? ""; const category = document.querySelector("[data-thread-filter='category']")?.value ?? ""; const sort = document.querySelector("[data-thread-filter='sort']")?.value ?? "new"; const threads = allThreads().filter((thread) => (!category || thread.category === category) && (!query || [thread.title, thread.body, thread.author, ...thread.replies.flatMap((reply) => [reply.author, reply.body])].join(" ").toLocaleLowerCase("ja").includes(query))).sort((a, b) => sort === "replies" ? b.replies.length - a.replies.length || String(b.created).localeCompare(String(a.created)) : String(b.created).localeCompare(String(a.created))); list.innerHTML = threads.length ? threads.map(threadRow).join("") : `<div class="empty-state">該当するスレッドはありません。</div>`; const line = document.querySelector("#thread-result-line"); if (line) line.innerHTML = `<strong>${threads.length}件</strong>を表示中`; }

function applyPartyRoute(route) {
  if (route.path !== "party") { partyShareError = ""; return; }
  const hasAction = route.query.has("add") || route.query.has("share"); if (!hasAction) return;
  const key = window.location.hash; if (consumedPartyQueries.has(key)) return; consumedPartyQueries.add(key);
  partyShareError = "";
  const addId = route.query.get("add");
  if (addId) {
    if (!characterById(addId)) partyShareError = "指定されたキャラIDは見つかりません。編成は変更していません。";
    else if (store.party.includes(addId)) partyShareError = "このキャラはすでに編成に入っています。重複追加はできません。";
    else if (store.party.length >= MAX_PARTY_SIZE) partyShareError = "編成は4枠までです。1枠外してから追加してください。";
    else { const result = commitMutation(() => store.party.push(addId)); flashMessage = mutationMessage(result, `${characterById(addId).name}を編成に追加しました。`); }
  }
  const encoded = route.query.get("share"); if (!encoded) return;
  const ids = encoded.split(",").filter(Boolean); const valid = ids.length === MAX_PARTY_SIZE && ids.every((id) => Boolean(characterById(id))) && new Set(ids).size === ids.length;
  if (!valid) { partyShareError = "共有URLのキャラIDが不正、または重複しています。編成は変更していません。"; return; }
  if (store.party.join(",") !== ids.join(",")) { const result = commitMutation(() => { store.party = ids; }); partyShareMessage = mutationMessage(result, "共有URLから4枠を復元しました。", "共有URLから4枠を復元しました。このセッション内のみの変更です。"); } else partyShareMessage = "共有URLの4枠を表示しています。";
}

function viewForRoute(route) { if (route.path === "home") return homeView(); if (route.path === "characters") return directoryView(); if (route.path.startsWith("character/")) { const character = characterById(route.path.split("/")[1]); return character ? detailView(character) : notFoundView("キャラ"); } if (route.path === "guides") return guidesView(); if (route.path.startsWith("guide/")) { const guide = guideById(route.path.split("/")[1]); return guide ? guideDetailView(guide, route) : notFoundView("攻略記事"); } if (route.path === "events") return eventsView(); if (route.path.startsWith("event/")) { const event = eventById(route.path.split("/")[1]); return event ? eventDetailView(event) : notFoundView("イベント"); } if (route.path === "community") return communityView(); if (route.path.startsWith("thread/")) { const thread = allThreads().find((item) => item.id === route.path.split("/")[1]); return thread ? threadDetailView(thread, route) : notFoundView("スレッド"); } if (route.path === "new-thread") return newThreadView(false); if (route.path === "new-thread/confirm") return newThreadDraft ? newThreadView(true) : newThreadView(false); if (route.path === "party") return partyView(); if (route.path === "bookmarks") return bookmarksView(route); if (route.path === "search") return searchView(route.query.get("q") ?? ""); return notFoundView(); }

function openModal(id) { const modal = document.querySelector(`#${id}`); if (modal) { modal.hidden = false; modal.querySelector("select, button, input")?.focus(); } }
function closeModal() { document.querySelectorAll(".modal-backdrop").forEach((modal) => { modal.hidden = true; }); }
function validation(formData, fields) { const values = {}; const errors = []; fields.forEach(({ key, label, min, max, allowBlank }) => { const value = formData.get(key)?.toString().trim() ?? ""; values[key] = value; if (!allowBlank && (value.length < min || value.length > max)) errors.push(`${label}は${min}〜${max}文字で入力してください。`); if (allowBlank && value.length > max) errors.push(`${label}は${max}文字以内で入力してください。`); }); return { values, errors }; }
function showFormErrors(form, errors) { const target = form.querySelector("[data-form-error]"); if (target) target.textContent = errors.join(" "); }

function bindInteractions(route) {
  document.querySelector("[data-search-form]")?.addEventListener("submit", (event) => { event.preventDefault(); const term = new FormData(event.currentTarget).get("q")?.toString().trim() ?? ""; if (term) window.location.hash = `search?q=${encodeURIComponent(term)}`; else document.querySelector("#header-search-input")?.focus(); });
  document.querySelector("[data-action='toggle-menu']")?.addEventListener("click", (event) => { const button = event.currentTarget; const nav = document.querySelector("#primary-nav"); const open = nav?.classList.toggle("is-open") ?? false; button.setAttribute("aria-expanded", String(open)); button.setAttribute("aria-label", open ? "メニューを閉じる" : "メニューを開く"); button.textContent = open ? "×" : "☰"; });
  document.querySelectorAll(".primary-nav a, .brand, .footer-links a").forEach((link) => link.addEventListener("click", closeMenu));
  document.querySelectorAll("[data-character-filter]").forEach((control) => control.addEventListener(control.matches("input") ? "input" : "change", renderCharacters));
  document.querySelector("[data-action='reset-character-filter']")?.addEventListener("click", () => { document.querySelectorAll("[data-character-filter]").forEach((control) => { control.value = control.dataset.characterFilter === "sort" ? "name" : ""; }); renderCharacters(); });
  document.querySelectorAll("[data-guide-filter]").forEach((control) => control.addEventListener(control.matches("input") ? "input" : "change", renderGuides));
  document.querySelector("[data-action='reset-guide-filter']")?.addEventListener("click", () => { document.querySelectorAll("[data-guide-filter]").forEach((control) => { control.value = ""; }); renderGuides(); });
  document.querySelectorAll("[data-thread-filter]").forEach((control) => control.addEventListener(control.matches("input") ? "input" : "change", renderThreads));
  document.querySelector("[data-action='reset-thread-filter']")?.addEventListener("click", () => { document.querySelectorAll("[data-thread-filter]").forEach((control) => { control.value = control.dataset.threadFilter === "sort" ? "new" : ""; }); renderThreads(); });
  document.querySelectorAll("[data-action='add-party'], [data-action='remove-party']").forEach((button) => button.addEventListener("click", () => { const id = button.dataset.characterId; if (button.dataset.action === "add-party") { if (store.party.includes(id)) partyShareError = "このキャラはすでに編成に入っています。重複追加はできません。"; else if (store.party.length >= MAX_PARTY_SIZE) partyShareError = "編成は4枠までです。1枠外してから追加してください。"; else { const result = commitMutation(() => store.party.push(id)); flashMessage = mutationMessage(result, `${characterById(id).name}を編成に追加しました。`); } } else { const result = commitMutation(() => { store.party = store.party.filter((memberId) => memberId !== id); }); flashMessage = mutationMessage(result, `${characterById(id).name}を編成から外しました。`); } render(); }));
  document.querySelectorAll("[data-action='toggle-bookmark']").forEach((button) => button.addEventListener("click", () => { const id = button.dataset.guideId; const saved = store.bookmarks.includes(id); const result = commitMutation(() => { store.bookmarks = saved ? store.bookmarks.filter((guideId) => guideId !== id) : [...store.bookmarks, id]; }); flashMessage = mutationMessage(result, saved ? "記事の保存を解除しました。" : "記事を保存しました。", saved ? "記事の保存を解除しました。このセッション内の変更です。" : "記事を保存しました。このセッション内の変更です。再読み込みで消える可能性があります。"); render(); }));
  document.querySelector("[data-new-thread-form]")?.addEventListener("submit", (event) => { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); const result = validation(data, [{ key: "title", label: "タイトル", min: 1, max: 80 }, { key: "author", label: "表示名", min: 1, max: 24 }, { key: "body", label: "本文", min: 1, max: 1000 }]); if (result.errors.length) return showFormErrors(form, result.errors); newThreadDraft = { ...result.values, category: data.get("category")?.toString() ?? "質問" }; window.location.hash = "new-thread/confirm"; });
  if (route.path === "new-thread" && newThreadDraft) { const category = document.querySelector("#new-category"); if (category) category.value = newThreadDraft.category; }
  document.querySelector("[data-action='new-thread-post']")?.addEventListener("click", () => { if (!newThreadDraft) return; const id = `u-thread-${Date.now().toString(36)}`; const draft = newThreadDraft; const result = commitMutation(() => store.userThreads.push({ id, title: draft.title, category: draft.category, author: draft.author, body: draft.body, created: new Date().toISOString(), owner: store.ownerId, replies: [] })); newThreadDraft = null; flashMessage = mutationMessage(result, `「${draft.title}」を投稿しました。`, `「${draft.title}」をこのセッションに投稿しました。再読み込みで消える可能性があります。`); window.location.hash = `thread/${id}`; });
  document.querySelectorAll("[data-reply-form]").forEach((form) => form.addEventListener("submit", (event) => { event.preventDefault(); const data = new FormData(form); const result = validation(data, [{ key: "body", label: "本文", min: 1, max: 1000 }, { key: "author", label: "表示名", min: 0, max: 24, allowBlank: true }]); if (result.errors.length) return showFormErrors(form, result.errors); const id = `u-reply-${Date.now().toString(36)}`; const mutation = commitMutation(() => store.userReplies.push({ id, threadId: form.dataset.threadId, author: result.values.author || "名無しの旅人", body: result.values.body, created: new Date().toISOString(), owner: store.ownerId })); flashMessage = mutationMessage(mutation, "返信を投稿しました。", "返信をこのセッションに投稿しました。再読み込みで消える可能性があります。"); render(); }));
  document.querySelectorAll("[data-edit-form]").forEach((form) => form.addEventListener("submit", (event) => { event.preventDefault(); const data = new FormData(form); const isThread = form.dataset.editKind === "thread"; const title = data.get("title")?.toString().trim() ?? ""; const body = data.get("body")?.toString().trim() ?? ""; const author = data.get("author")?.toString().trim() ?? ""; const errors = []; if (isThread && !validText(title, 1, 80)) errors.push("タイトルは1〜80文字で入力してください。"); if (!validText(body, 1, 1000)) errors.push("本文は1〜1000文字で入力してください。"); if (isThread && !validText(author, 1, 24)) errors.push("表示名は1〜24文字で入力してください。"); if (!isThread && author.length > 24) errors.push("表示名は24文字以内で入力してください。"); if (errors.length) return showFormErrors(form, errors); const mutation = commitMutation(() => { store.edits[form.dataset.editId] = isThread ? { title, author, body } : { author: author || "名無しの旅人", body }; }); flashMessage = mutationMessage(mutation, "自分の投稿を更新しました。", "自分の投稿をこのセッション内で更新しました。再読み込みで消える可能性があります。"); navigateOrRender(`thread/${form.dataset.threadId}`); }));
  document.querySelectorAll("[data-action='report-open']").forEach((button) => button.addEventListener("click", () => { const modal = document.querySelector("#action-modal"); modal?.querySelector("[name='postId']")?.setAttribute("value", button.dataset.reportId); openModal("action-modal"); }));
  document.querySelector("[data-report-form]")?.addEventListener("submit", (event) => { event.preventDefault(); const data = new FormData(event.currentTarget); const reason = data.get("reason")?.toString() ?? ""; if (!reason) return; const mutation = commitMutation(() => store.reports.push({ id: data.get("postId")?.toString(), reason, created: new Date().toISOString() })); closeModal(); flashMessage = mutationMessage(mutation, "通報デモを完了しました。元の投稿は表示したままです。", "通報デモを完了しました。元の投稿は表示したままです。記録はこのセッション内です。"); render(); });
  document.querySelectorAll("[data-action='delete-open']").forEach((button) => button.addEventListener("click", () => { const modal = document.querySelector("#action-modal"); if (!modal) return; modal.querySelector(".modal").innerHTML = `<button class="modal-close" type="button" data-action="modal-close" aria-label="閉じる">×</button><p class="eyebrow">DELETE / CONFIRM</p><h2>この投稿を削除しますか？</h2><p>取消なら投稿は残ります。確定すると自分の投稿だけを非表示にします。</p><div class="action-row"><button class="subtle-button" type="button" data-action="modal-close">取消</button><button class="primary-button" type="button" data-action="delete-confirm" data-delete-kind="${button.dataset.deleteKind}" data-delete-id="${button.dataset.deleteId}" data-thread-id="${button.dataset.threadId}">削除を確定</button></div>`; bindModalActions(); openModal("action-modal"); }));
  document.querySelector("[data-action='delete-confirm']")?.addEventListener("click", (event) => { const button = event.currentTarget; const mutation = commitMutation(() => store.deleted.push(button.dataset.deleteId)); closeModal(); flashMessage = mutationMessage(mutation, "自分の投稿を削除しました。", "自分の投稿をこのセッション内で削除しました。再読み込みで消える可能性があります。"); navigateOrRender(button.dataset.deleteKind === "thread" ? "community" : `thread/${button.dataset.threadId}`); });
  document.querySelectorAll("[data-action='modal-close'], [data-action='reset-cancel']").forEach((button) => button.addEventListener("click", closeModal));
  document.querySelector("[data-action='reset-open']")?.addEventListener("click", () => openModal("reset-modal"));
  document.querySelector("[data-action='reset-confirm']")?.addEventListener("click", () => { try { window.localStorage.removeItem(STORAGE_KEY); const currentOwner = store.ownerId; store = blankStore(currentOwner); storageMode = "persistent"; storageNotice = ""; partyShareMessage = ""; partyShareError = ""; flashMessage = "保存データを初期状態に戻しました。"; closeModal(); render(); } catch { storageMode = "temporary"; storageNotice = "保存先を利用できないため、初期化できませんでした。一時利用モードで表示しています。"; flashMessage = "保存データを初期化できませんでした。現在の表示は維持しています。"; closeModal(); render(); } });
  document.querySelector("[data-action='copy-party-url']")?.addEventListener("click", async () => { const input = document.querySelector("#party-share-url"); const url = input?.value ?? ""; try { if (!navigator.clipboard?.writeText) throw new Error("clipboard unavailable"); await navigator.clipboard.writeText(url); partyShareMessage = "編成URLをコピーしました。"; render(); } catch { partyShareMessage = "コピーできないため、共有URLを選択しました。Ctrl+Cでコピーできます。"; render(); requestAnimationFrame(() => { const nextInput = document.querySelector("#party-share-url"); nextInput?.focus(); nextInput?.select(); }); } });
  if (!skipLinkBound) { document.querySelector(".skip-link")?.addEventListener("click", (event) => { event.preventDefault(); const main = document.querySelector("#main-content"); main?.focus({ preventScroll: true }); main?.scrollIntoView({ behavior: "smooth", block: "start" }); }); skipLinkBound = true; }
  if (route.path === "characters") renderCharacters(); if (route.path === "guides") renderGuides(); if (route.path === "community") renderThreads();
}

function bindModalActions() { document.querySelectorAll("[data-action='modal-close']").forEach((button) => button.addEventListener("click", closeModal)); document.querySelector("[data-action='delete-confirm']")?.addEventListener("click", (event) => { const button = event.currentTarget; const mutation = commitMutation(() => store.deleted.push(button.dataset.deleteId)); closeModal(); flashMessage = mutationMessage(mutation, "自分の投稿を削除しました。", "自分の投稿をこのセッション内で削除しました。再読み込みで消える可能性があります。"); navigateOrRender(button.dataset.deleteKind === "thread" ? "community" : `thread/${button.dataset.threadId}`); }); }
function closeMenu() { const nav = document.querySelector("#primary-nav"); const button = document.querySelector("[data-action='toggle-menu']"); nav?.classList.remove("is-open"); button?.setAttribute("aria-expanded", "false"); if (button) { button.setAttribute("aria-label", "メニューを開く"); button.textContent = "☰"; } }

function render() { if (!content) return; const route = parseRoute(); closeMenu(); applyPartyRoute(route); app.innerHTML = `${headerTemplate(route)}<main id="main-content" tabindex="-1"><div class="main-inner">${viewForRoute(route)}</div></main>${footerTemplate()}`; bindInteractions(route); document.title = route.path.startsWith("character/") && characterById(route.path.split("/")[1]) ? `${characterById(route.path.split("/")[1]).name} | 星環クロニクル攻略室` : route.path.startsWith("guide/") && guideById(route.path.split("/")[1]) ? `${guideById(route.path.split("/")[1]).title} | 星環クロニクル攻略室` : "星環クロニクル攻略室"; window.scrollTo({ top: 0, behavior: "auto" }); if (route.path.startsWith("guide/") && route.query.has("section")) { const guideId = route.path.split("/")[1]; const index = Number(route.query.get("section")); if (Number.isInteger(index) && index >= 0 && index < (guideById(guideId)?.sections.length ?? 0)) requestAnimationFrame(() => document.querySelector(`#guide-${guideId}-section-${index}`)?.scrollIntoView({ behavior: "auto", block: "start" })); } }
async function loadContent() { try { const response = await fetch(FIXTURE_URL, { cache: "no-store" }); if (!response.ok) throw new Error(`HTTP ${response.status}`); content = await response.json(); store = loadStore(); render(); } catch (error) { app.innerHTML = `<div class="main-inner"><div class="error-state" role="alert"><strong>記録を読み込めませんでした。</strong><p>ローカルサーバー経由で再読み込みしてください。(${escapeHTML(error.message)})</p></div></div>`; } }

window.addEventListener("hashchange", () => { partyShareMessage = ""; render(); });
window.addEventListener("keydown", (event) => { if (event.key === "Escape") { closeMenu(); closeModal(); } });
loadContent();
